const socket = io();

let currentChannelId = null;

function login() {
    const token = document.getElementById('tokenInput').value;
    if (!token) return;
    
    document.getElementById('status').innerText = 'Connecting...';
    socket.emit('login-bot', token);
}

socket.on('bot-ready', (tag) => {
    document.getElementById('login-screen').classList.add('hidden');
    document.getElementById('app-screen').classList.remove('hidden');
});

socket.on('login-error', (err) => {
    document.getElementById('status').innerText = `Error: ${err}`;
});

socket.on('guilds-list', (guilds) => {
    const guildListDiv = document.getElementById('guild-list');
    guildListDiv.innerHTML = '';
    
    guilds.forEach(guild => {
        const guildDiv = document.createElement('div');
        guildDiv.className = 'guild-item';
        guildDiv.innerText = guild.name;
        guildDiv.style.cursor = 'pointer';
        guildDiv.style.padding = '8px';
        guildDiv.style.margin = '4px 0';
        guildDiv.style.borderRadius = '4px';
        guildDiv.style.backgroundColor = '#35373c';
        
        guildDiv.onclick = () => loadChannels(guild.id);
        guildListDiv.appendChild(guildDiv);
    });
});

function loadChannels(guildId) {
    socket.emit('get-channels', guildId);
}

socket.on('channels-list', (channels) => {
    const guildListDiv = document.getElementById('guild-list');
    // Clear and show channels for the selected guild
    guildListDiv.innerHTML = '<h4>Channels</h4>';
    
    channels.forEach(channel => {
        const chanDiv = document.createElement('div');
        chanDiv.className = 'channel-item';
        chanDiv.innerText = `# ${channel.name}`;
        chanDiv.style.cursor = 'pointer';
        chanDiv.style.padding = '6px';
        chanDiv.style.margin = '2px 0';
        chanDiv.style.borderRadius = '4px';
        
        chanDiv.onclick = () => selectChannel(channel.id, channel.name);
        guildListDiv.appendChild(chanDiv);
    });
});

function selectChannel(channelId, channelName) {
    currentChannelId = channelId;
    document.getElementById('channel-header').innerText = `# ${channelName}`;
    document.getElementById('chat').innerHTML = '';
    socket.emit('get-messages', channelId);
}

socket.on('message-history', (messages) => {
    const chat = document.getElementById('chat');
    chat.innerHTML = '';
    messages.reverse().forEach(msg => appendMessage(msg));
});

socket.on('new-message', (msg) => {
    if (msg.channelId === currentChannelId) {
        appendMessage(msg);
    }
});

function appendMessage(msg) {
    const chat = document.getElementById('chat');
    const p = document.createElement('p');
    p.innerHTML = `<b>${msg.author}:</b> ${msg.content}`;
    p.style.margin = '4px 0';
    chat.appendChild(p);
    chat.scrollTop = chat.scrollHeight;
}

function sendMessage() {
    const input = document.getElementById('messageInput');
    const content = input.value;
    if (!content || !currentChannelId) return;

    socket.emit('send-message', { channelId: currentChannelId, content });
    input.value = '';
}

function checkEnter(event) {
    if (event.key === 'Enter') {
        sendMessage();
    }
}
